CREATE TABLE CPF_BATCH_EXECUTION_CONTROL_R89_BAK AS SELECT * FROM CPF_BATCH_EXECUTION_CONTROL;
CREATE TABLE CPF_BATCH_EXECUTION_EPOCH_R89_BAK AS SELECT * FROM CPF_BATCH_EXECUTION_EPOCH;
SET @cpf_r89_dupes := (SELECT COUNT(*) FROM (SELECT idempotency_key FROM CPF_BATCH_EXECUTION_CONTROL GROUP BY idempotency_key HAVING COUNT(*) > 1) x);
SET @cpf_r89_guard := IF(@cpf_r89_dupes = 0, 'SELECT 1', 'SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''R89 cannot restore global idempotency uniqueness; checkpoint retained''');
PREPARE cpf_r89_stmt FROM @cpf_r89_guard; EXECUTE cpf_r89_stmt; DEALLOCATE PREPARE cpf_r89_stmt;
DROP TABLE CPF_BATCH_EXECUTION_EPOCH;
DROP INDEX IX_CPF_BAT_EXEC_RECONCILE ON CPF_BATCH_EXECUTION_CONTROL;
DROP INDEX UK_CPF_BAT_EXEC_IDEM_SCOPE ON CPF_BATCH_EXECUTION_CONTROL;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL
  DROP CONSTRAINT CK_CPF_BAT_REQUEST_HASH,
  DROP CONSTRAINT CK_CPF_BAT_PLAN_HASH,
  DROP CONSTRAINT CK_CPF_BAT_CONTROL_VERSION,
  DROP CONSTRAINT CK_CPF_BAT_RECONCILE_ATTEMPT,
  DROP COLUMN idempotency_scope,
  DROP COLUMN request_hash,
  DROP COLUMN plan_checksum,
  DROP COLUMN control_version,
  DROP COLUMN reconcile_attempts,
  DROP COLUMN reconcile_after,
  DROP COLUMN last_error_code,
  DROP COLUMN last_error_detail,
  ADD UNIQUE INDEX UK_CPF_BAT_EXEC_IDEM_LEGACY(idempotency_key);
